/**
 * "Blocked by" links between issues. A row means `issue_id` is blocked by `blocker_id`; both issues live in the same organization.
 *
 * Must call (do not reimplement): shouldFilterArchived (via livePredicate)
 */
import { and, asc, eq, inArray, notInArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { brandId, toIssue, toIssueDependency } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";
import type { SQL } from "drizzle-orm";

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toIssueDependency(row) : null;
}

/**
 * Idempotent: an existing link is returned as-is rather than duplicated, so a
 * double submit cannot leave two rows behind.
 */
export async function insertDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
  createdBy: UserId,
): Promise<IssueDependency> {
  getDb()
    .insert(issueDependencies)
    .values({
      orgId,
      issueId,
      blockerId,
      createdBy,
      createdAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing()
    .run();

  const link = await findDependency(orgId, issueId, blockerId);
  if (!link) throw new Error(`Dependency ${issueId} -> ${blockerId} not stored`);
  return link;
}

/** Resolves `true` when a link was removed, `false` when there was none. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const result = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .run();
  return result.changes > 0;
}

/** Ids of every issue blocking any of `issueIds`, archived or not. */
export async function listBlockerIds(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly IssueId[]> {
  if (issueIds.length === 0) return [];

  const rows = getDb()
    .select({ blockerId: issueDependencies.blockerId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        inArray(issueDependencies.issueId, [...issueIds]),
      ),
    )
    .all();
  return rows.map((row) => brandId<IssueId>(row.blockerId));
}

/** Ids of every issue blocked by any of `blockerIds`, archived or not. */
export async function listBlockedIssueIds(
  orgId: OrgId,
  blockerIds: readonly IssueId[],
): Promise<readonly IssueId[]> {
  if (blockerIds.length === 0) return [];

  const rows = getDb()
    .select({ issueId: issueDependencies.issueId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        inArray(issueDependencies.blockerId, [...blockerIds]),
      ),
    )
    .all();
  return [...new Set(rows.map((row) => brandId<IssueId>(row.issueId)))];
}

/** Live blocker issues of `issueId`, ordered by issue number. */
export async function listBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  return selectBlockers(orgId, issueId);
}

/** Live blockers of `issueId` whose status is neither `done` nor `canceled`. */
export async function listOpenBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  return selectBlockers(
    orgId,
    issueId,
    notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
  );
}

async function selectBlockers(
  orgId: OrgId,
  issueId: IssueId,
  extra?: SQL,
): Promise<readonly Issue[]> {
  const db = getDb();
  const rows = db
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          livePredicate(issues.archivedAt, {}),
          inArray(
            issues.id,
            db
              .select({ id: issueDependencies.blockerId })
              .from(issueDependencies)
              .where(
                and(
                  orgPredicate(issueDependencies.orgId, orgId),
                  eq(issueDependencies.issueId, issueId),
                ),
              ),
          ),
          extra,
        ),
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

