/**
 * Issue dependencies ("blocked by" links): who may link what, cycle prevention, and telling an assignee when the last open blocker of their issue closes.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, notify, subscribe
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived, isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { notify } from "./notification-service";
import { issueResource, requireFound } from "./_support";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";

export { IssueBlockedError } from "./_support";

type BlockerInput = { orgId: OrgId; issueId: IssueId; blockerId: IssueId };

/**
 * Records "`issueId` is blocked by `blockerId`". Linking is an edit of the
 * blocked issue, so it needs `issue:update` on that issue only. Re-adding an
 * existing link returns it unchanged.
 */
export async function addBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    issue.id,
    blocker.id,
  );
  if (existing) return existing;

  if (issue.id === blocker.id) {
    throw new Error(`Issue ${issue.id} cannot block itself`);
  }
  if (await isReachable(input.orgId, blocker.id, issue.id)) {
    throw new Error(
      `Issue ${blocker.id} is already blocked by ${issue.id}; linking would create a cycle`,
    );
  }

  return dependencyRepo.insertDependency(
    input.orgId,
    issue.id,
    blocker.id,
    actor.userId,
  );
}

/** Resolves `true` when a link was removed and `false` when there was none. */
export async function removeBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(input.orgId, issue.id, input.blockerId);
}

/** Live blockers of an issue, open or closed, ordered by issue number. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listBlockers(orgId, issue.id);
}

/**
 * The "you are unblocked" reaction. A blocker closes when its status enters
 * `done`/`canceled` from an open status, or when it is archived (alone or with
 * its project) while still open; closed → closed changes never notify.
 */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, [payload.issueId], payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (!issue || isClosedStatus(issue.status)) return;
      await notifyUnblocked(payload.orgId, [issue.id], payload.actorId);
    }),
    subscribe("project.archived", async (payload) => {
      const closed: IssueId[] = [];
      for (const issueId of payload.archivedIssueIds) {
        const issue = await issueRepo.findIssueById(payload.orgId, issueId);
        if (issue && !isClosedStatus(issue.status)) closed.push(issue.id);
      }
      await notifyUnblocked(payload.orgId, closed, payload.actorId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/** True when `target` can be reached from `from` by following blocker links. */
async function isReachable(
  orgId: OrgId,
  from: IssueId,
  target: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>([from]);
  let frontier: readonly IssueId[] = [from];

  while (frontier.length > 0) {
    const next: IssueId[] = [];
    for (const id of await dependencyRepo.listBlockerIds(orgId, frontier)) {
      if (id === target) return true;
      if (seen.has(id)) continue;
      seen.add(id);
      next.push(id);
    }
    frontier = next;
  }

  return false;
}

/**
 * Notifies the assignee of every live, still-open issue blocked by one of
 * `closedBlockerIds` that has no open blocker left — once per issue, however
 * many of its blockers closed together.
 */
async function notifyUnblocked(
  orgId: OrgId,
  closedBlockerIds: readonly IssueId[],
  actorId: UserId | null,
): Promise<void> {
  const blockedIds = await dependencyRepo.listBlockedIssueIds(
    orgId,
    closedBlockerIds,
  );

  for (const blockedId of blockedIds) {
    const issue = await issueRepo.findIssueById(orgId, blockedId);
    if (!issue || isArchived(issue) || isClosedStatus(issue.status)) continue;
    if (issue.assigneeId === null) continue;

    const open = await dependencyRepo.listOpenBlockers(orgId, issue.id);
    if (open.length > 0) continue;

    await notify(orgId, "issue_unblocked", [issue.assigneeId], {
      title: "An issue you are assigned is unblocked",
      body: `Issue #${issue.number} "${issue.title}" has no open blockers left`,
      href: `/issues/${issue.id}`,
      actorId,
    });
  }
}

