  input: BlockerInput,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(input.orgId, issue.id, input.blockerId);
}

/** Live blockers of an issue, open or closed, ordered by issue number. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listBlockers(orgId, issue.id);
}

/**
 * The "you are unblocked" reaction. A blocker closes when its status enters
 * `done`/`canceled` from an open status, or when it is archived (alone or with
 * its project) while still open; closed → closed changes never notify.
 */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, [payload.issueId], payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (!issue || isClosedStatus(issue.status)) return;
      await notifyUnblocked(payload.orgId, [issue.id], payload.actorId);
    }),
    subscribe("project.archived", async (payload) => {
      const closed: IssueId[] = [];
      for (const issueId of payload.archivedIssueIds) {
        const issue = await issueRepo.findIssueById(payload.orgId, issueId);
        if (issue && !isClosedStatus(issue.status)) closed.push(issue.id);
      }
      await notifyUnblocked(payload.orgId, closed, payload.actorId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
