 * Notifies the assignee of every live, still-open issue blocked by one of
 * `closedBlockerIds` that has no open blocker left — once per issue, however
 * many of its blockers closed together.
 */
async function notifyUnblocked(
  orgId: OrgId,
  closedBlockerIds: readonly IssueId[],
  actorId: UserId | null,
): Promise<void> {
  const blockedIds = await dependencyRepo.listBlockedIssueIds(
    orgId,
    closedBlockerIds,
  );

  for (const blockedId of blockedIds) {
    const issue = await issueRepo.findIssueById(orgId, blockedId);
    if (!issue || isArchived(issue) || isClosedStatus(issue.status)) continue;
    if (issue.assigneeId === null) continue;

    const open = await dependencyRepo.listOpenBlockers(orgId, issue.id);
    if (open.length > 0) continue;

    await notify(orgId, "issue_unblocked", [issue.assigneeId], {
      title: "An issue you are assigned is unblocked",
      body: `Issue #${issue.number} "${issue.title}" has no open blockers left`,
      href: `/issues/${issue.id}`,
      actorId,
    });
  }
}

