let other: Tenant;
beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("deps");
  other = await createTenant("other");
  registerEventHandlers();
});
afterAll(() => cleanup());

async function mk(title: string, assigneeId: any = null) {
  return issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { title, assigneeId }));
}
async function unblockedFor(userId: any) {
  const page = await notificationRepo.listNotifications({ orgId: t.org.id, recipientId: userId, unreadOnly: false, limit: 100, cursor: null } as any);
  return page.items.filter((n) => n.kind === "issue_unblocked");
}

