  it("schema accepts kind", () => {
    expect(updateNotificationPreferenceSchema.safeParse({ orgId: t.org.id, userId: t.userIds.member, kind: "issue_unblocked", inApp: false, email: false, digestOnly: false }).success).toBe(true);
  });
  it("add / list / remove / errors", async () => {
    const a = await mk("Issue A");
    const b = await mk("Issue B");
    const c = await mk("Issue C");
    const link = await dep.addBlocker(t.actors.member, { orgId: t.org.id, issueId: a.id, blockerId: b.id });
    expect(link).toMatchObject({ orgId: t.org.id, issueId: a.id, blockerId: b.id, createdBy: t.userIds.member });
    const again = await dep.addBlocker(t.actors.admin, { orgId: t.org.id, issueId: a.id, blockerId: b.id });
    expect(again).toEqual(link);
    await expect(dep.addBlocker(t.actors.member, { orgId: t.org.id, issueId: b.id, blockerId: a.id })).rejects.toThrow();
    await dep.addBlocker(t.actors.member, { orgId: t.org.id, issueId: b.id, blockerId: c.id });
    await expect(dep.addBlocker(t.actors.member, { orgId: t.org.id, issueId: c.id, blockerId: a.id })).rejects.toThrow();
    await expect(dep.addBlocker(t.actors.member, { orgId: t.org.id, issueId: c.id, blockerId: c.id })).rejects.toThrow();
    await expect(dep.addBlocker(t.actors.viewer, { orgId: t.org.id, issueId: c.id, blockerId: b.id })).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(dep.addBlocker(t.actors.member, { orgId: other.org.id, issueId: c.id, blockerId: b.id })).rejects.toBeInstanceOf(TenantScopeError);
    const foreign = await issueService.createIssue(other.actors.owner, issueInput(other.org.id, other.project.id));
    await expect(dep.addBlocker(t.actors.member, { orgId: t.org.id, issueId: c.id, blockerId: foreign.id })).rejects.toBeInstanceOf(NotFoundError);
    await expect(dep.removeBlocker(t.actors.member, { orgId: t.org.id, issueId: foreign.id, blockerId: c.id })).rejects.toBeInstanceOf(NotFoundError);
    expect(await dep.removeBlocker(t.actors.member, { orgId: t.org.id, issueId: c.id, blockerId: "nope" as any })).toBe(false);
